const axios = require('axios');

const api = axios.create({ baseURL: process.env.CATALOG_URL, timeout: 4000 });

api.interceptors.request.use((config) => {
  config.headers['X-Request-Source'] = 'catalog-sync';
  return config;
});

async function listProducts(page) {
  const { data } = await api.get('/products', { params: { page, limit: 50 } });
  return data.items;
}

async function getProduct(id) {
  try {
    const { data } = await api.get(`/products/${id}`);
    return data;
  } catch (err) {
    if (axios.isAxiosError(err) && err.response && err.response.status === 404) return null;
    throw err;
  }
}

module.exports = { listProducts, getProduct };

