var chalk = require('chalk');

function ok(msg) {
  console.log(chalk.green('OK  ') + msg);
}

function warn(msg) {
  console.log(chalk.yellow('WARN ') + msg);
}

function fail(msg) {
  console.error(chalk.red('FAIL ') + msg);
  process.exitCode = 1;
}

var env = process.env.DEPLOY_ENV || 'staging';
ok('Deploy target: ' + env);
if (env === 'production') warn('Deploying to production');
if (!process.env.DEPLOY_TAG) fail('DEPLOY_TAG is not set');

