var got = require('got');

// The legacy intake endpoint answers every POST with a 302 to the stored file's URL;
// we rely on got following it and hand the final body back to the caller.
module.exports = function uploadReceipt(buffer, cb) {
  got(process.env.INTAKE_URL + '/receipts', {
    method: 'POST',
    body: buffer,
    headers: { 'content-type': 'application/pdf' }
  }, function (err, body, res) {
    if (err) return cb(err);
    cb(null, { location: res.url, stored: JSON.parse(body) });
  });
};

