const semver = require('semver');

const MIN_CLIENT = '2.4.0';

function isSupportedClient(versionHeader) {
  const v = semver.valid(semver.clean(versionHeader || ''));
  if (!v) return false;
  return semver.gte(v, MIN_CLIENT);
}

function pluginMatches(range, version) {
  return semver.satisfies(version, range);
}

module.exports = { isSupportedClient, pluginMatches };

