const semver = require('semver');

function nextVersion(current, kind) {
  const coerced = semver.coerce(current);
  if (!coerced) throw new Error(`not a version: ${current}`);
  return semver.inc(coerced.version, kind);
}

function newest(versions) {
  return versions.filter((v) => semver.valid(v)).sort(semver.rcompare)[0];
}

module.exports = { nextVersion, newest };

