const express = require('express');

const router = express.Router();
const CATALOG = require('../catalog.json');

// Users type a version range in the search box.
router.get('/plugins', (req, res) => {
  const range = semver.validRange(String(req.query.range || '*'));
  if (!range) return res.status(400).json({ error: 'invalid range' });
  const hits = CATALOG.filter((p) => semver.satisfies(p.version, range));
  res.json(hits);
});

