import { Server } from 'socket.io';

export function attach(io: Server) {
  io.on('connection', (socket) => {
    socket.on('ready', () => socket.join('workers'));
  });
}

export function requestStatus(io: Server): Promise<unknown[]> {
  return new Promise((resolve, reject) => {
    io.to('workers').timeout(2000).emit('status', (err: Error | null, replies: unknown[]) => {
      if (err) return reject(err);
      resolve(replies);
    });
  });
}

