from decimal import Decimal


async def quote_total(items: list[dict], tax_rate: Decimal) -> Decimal:
    subtotal = sum((Decimal(str(i["price"])) * i["qty"] for i in items), Decimal("0"))
    return (subtotal * (1 + tax_rate)).quantize(Decimal("0.01"))


def apply_discount(total: Decimal, percent: int) -> Decimal:
    if percent <= 0:
        return total
    return total - (total * Decimal(percent) / 100)

