from werkzeug.middleware.proxy_fix import ProxyFix
from werkzeug.wrappers import Request, Response


@Request.application
def application(request):
    return Response(f"client {request.remote_addr}", mimetype="text/plain")


app = ProxyFix(application, x_for=1, x_proto=1)

