import os

from werkzeug.utils import secure_filename
from werkzeug.wrappers import Request, Response

MAX_UPLOAD = 10 * 1024 * 1024


@Request.application
def application(request):
    request.max_content_length = MAX_UPLOAD
    upload = request.files.get("attachment")
    comment = request.form.get("comment", "")
    if upload is None:
        return Response("no file", status=400)
    upload.save(os.path.join(os.environ.get("INBOX_DIR", "inbox"), secure_filename(upload.filename)))
    return Response(f"saved, comment length {len(comment)}")
